def validar_uf(uf: str) -> bool:
    """Verifica se a UF informada é um estado brasileiro válido."""
    ufs_validas = {
        "AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO",
        "MA", "MT", "MS", "MG", "PA", "PB", "PR", "PE", "PI",
        "RJ", "RN", "RS", "RO", "RR", "SC", "SP", "SE", "TO",
    }
    return uf.upper() in ufs_validas

class RateLimiter:
    """Garante um intervalo mínimo entre requisições."""
    def __init__(self, delay: float = Config.RATE_LIMIT_DELAY):
        self._delay = delay
        self._last: float = 0.0
    def wait(self) -> None:
        elapsed = time.monotonic() - self._last
        if elapsed < self._delay:
            time.sleep(self._delay - elapsed)
        self._last = time.monotonic()

